protocol CustomerSource { func find(_ id: String) async throws -> Customer? }
func enrich(_ order: Order, using source: CustomerSource) async throws -> Order {
    guard let c = try await source.find(order.customerId) else { return order }   // degrade
    return Order(customerId: order.customerId, customerName: c.name, region: c.region)
}
struct EnrichMiddleware: AsyncMiddleware {   // responder-chain insertion point (Vapor)
    let source: CustomerSource
    func respond(to req: Request, chainingTo next: AsyncResponder) async throws -> Response {
        req.customer = try await source.find(req.parameters.get("id") ?? "")      // enrich
        return try await next.respond(to: req)
    }
}
